import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64

.visible .entry conv2d_kernel(
    .param .u64 input_ptr,
    .param .u64 weight_ptr,
    .param .u64 bias_ptr,
    .param .u64 output_ptr,
    .param .u32 total_elements
)
{
    .reg .pred %p<20>;
    .reg .s32 %r<64>;
    .reg .s64 %rd<48>;
    .reg .f32 %f<24>;

    ld.param.u64 %rd1, [input_ptr];
    ld.param.u64 %rd2, [weight_ptr];
    ld.param.u64 %rd3, [bias_ptr];
    ld.param.u64 %rd4, [output_ptr];
    ld.param.u32 %r1, [total_elements];

    cvta.to.global.u64 %rd1, %rd1;
    cvta.to.global.u64 %rd2, %rd2;
    cvta.to.global.u64 %rd3, %rd3;
    cvta.to.global.u64 %rd4, %rd4;

    mov.u32 %r2, %ctaid.x;
    mov.u32 %r3, %ntid.x;
    mov.u32 %r4, %tid.x;
    mad.lo.s32 %r5, %r2, %r3, %r4;

    setp.ge.s32 %p1, %r5, %r1;
    @%p1 bra DONE;

    // ow = tid % 55, tmp1 = tid / 55
    div.s32 %r6, %r5, 55;
    rem.s32 %r7, %r5, 55;
    // oh = tmp1 % 55, tmp2 = tmp1 / 55
    div.s32 %r8, %r6, 55;
    rem.s32 %r9, %r6, 55;
    // oc = tmp2 % 96, n = tmp2 / 96
    div.s32 %r10, %r8, 96;
    rem.s32 %r11, %r8, 96;

    // n=%r10, oc=%r11, oh=%r9, ow=%r7

    mul.wide.s32 %rd10, %r11, 4;
    add.s64 %rd11, %rd3, %rd10;
    ld.global.f32 %f1, [%rd11];

    mov.s32 %r12, 0;
IC_LOOP:
    setp.ge.s32 %p2, %r12, 3;
    @%p2 bra IC_DONE;

    mov.s32 %r13, 0;
KH_LOOP:
    setp.ge.s32 %p3, %r13, 11;
    @%p3 bra KH_DONE;

    mul.lo.s32 %r14, %r9, 4;
    add.s32 %r14, %r14, %r13;
    sub.s32 %r14, %r14, 2;

    setp.lt.s32 %p4, %r14, 0;
    setp.ge.s32 %p5, %r14, 224;
    or.pred %p6, %p4, %p5;
    @%p6 bra KH_SKIP;

    mov.s32 %r15, 0;
KW_LOOP:
    setp.ge.s32 %p7, %r15, 11;
    @%p7 bra KW_DONE;

    mul.lo.s32 %r16, %r7, 4;
    add.s32 %r16, %r16, %r15;
    sub.s32 %r16, %r16, 2;

    setp.lt.s32 %p8, %r16, 0;
    setp.ge.s32 %p9, %r16, 224;
    or.pred %p10, %p8, %p9;
    @%p10 bra KW_SKIP;

    mad.lo.s32 %r17, %r10, 3, %r12;
    mad.lo.s32 %r17, %r17, 224, %r14;
    mad.lo.s32 %r17, %r17, 224, %r16;

    mul.wide.s32 %rd12, %r17, 4;
    add.s64 %rd13, %rd1, %rd12;
    ld.global.f32 %f2, [%rd13];

    mad.lo.s32 %r18, %r11, 3, %r12;
    mad.lo.s32 %r18, %r18, 11, %r13;
    mad.lo.s32 %r18, %r18, 11, %r15;

    mul.wide.s32 %rd14, %r18, 4;
    add.s64 %rd15, %rd2, %rd14;
    ld.global.f32 %f3, [%rd15];

    fma.rn.f32 %f1, %f2, %f3, %f1;

KW_SKIP:
    add.s32 %r15, %r15, 1;
    bra KW_LOOP;
KW_DONE:

KH_SKIP:
    add.s32 %r13, %r13, 1;
    bra KH_LOOP;
KH_DONE:

    add.s32 %r12, %r12, 1;
    bra IC_LOOP;
IC_DONE:

    mad.lo.s32 %r19, %r10, 96, %r11;
    mad.lo.s32 %r19, %r19, 55, %r9;
    mad.lo.s32 %r19, %r19, 55, %r7;

    mul.wide.s32 %rd16, %r19, 4;
    add.s64 %rd17, %rd4, %rd16;
    st.global.f32 [%rd17], %f1;

DONE:
    ret;
}
